select public.prepify_load_bank('Chemistry', 14, $j$[["Hydrocarbons are compounds made of:",["carbon and oxygen","carbon and hydrogen","hydrogen and oxygen","carbon, hydrogen and nitrogen"],"B",1,0,"d6dc9122f7e7",0],["The general formula of alkanes is:",["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙHₙ"],"A",1,0,"608994cbfd39",0],["The general formula of alkenes is:",["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙH₂ₙ₊₁"],"B",1,0,"133e8b7a8c6b",0],["The general formula of alkynes is:",["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙH₂ₙ₊₄"],"C",3,0,"a8226fbd4fc2",0],["Alkanes are called saturated hydrocarbons because they contain:",["only single bonds between carbon atoms","at least one double bond","a triple bond","no hydrogen"],"A",3,0,"fef0018be32e",0],["The simplest alkane is:",["ethane","methane","ethene","ethyne"],"B",1,0,"c85038edc49a",0],["The molecular formula of an alkane with 5 carbon atoms is:",["C₅H₁₀","C₅H₁₂","C₅H₈","C₅H₁₄"],"B",5,0,"e50bce0a5269",0],["The molecular formula of an alkene with 3 carbon atoms is:",["C₃H₈","C₃H₆","C₃H₄","C₃H₃"],"B",5,0,"7aaf91744c24",0],["The molecular formula of an alkyne with 4 carbon atoms is:",["C₄H₁₀","C₄H₈","C₄H₆","C₄H₄"],"C",5,0,"f4d475e4a8c3",0],["Ethene (C₂H₄) contains a:",["single bond only","carbon–carbon double bond","carbon–carbon triple bond","benzene ring"],"B",3,0,"95a466a22bfb",0],["Ethyne (C₂H₂) is commonly called:",["methane","acetylene","propane","butane"],"B",3,0,"b6a961e54593",0],["The gas used with oxygen in welding torches is:",["methane","ethyne (acetylene)","propane","ethane"],"B",3,1,"7e636a27683f",0],["When bromine water is shaken with an alkene, it:",["turns from orange-brown to colourless","turns blue","turns red","stays orange-brown"],"A",3,0,"1ba3013fe8b5",0],["A student shakes two gases with bromine water. Gas X decolourizes it; gas Y does not. Which statement is correct?",["X is unsaturated and Y is saturated","X is saturated and Y is unsaturated","Both are alkanes","Both are alkenes"],"A",5,1,"370ea673df01",0],["Alkanes react with chlorine in sunlight by:",["addition","substitution","polymerization","neutralization"],"B",3,0,"2e132f4ecc12",0],["Alkenes typically undergo:",["addition reactions","substitution reactions only","no reactions","neutralization"],"A",3,0,"e4a94939eb8e",0],["Adding hydrogen to an alkene in the presence of a nickel catalyst is called:",["hydration","hydrogenation","halogenation","cracking"],"B",3,0,"f950f1f6f39c",0],["Vegetable ghee (margarine) is made from vegetable oils by:",["hydrogenation","dehydration","combustion","fermentation"],"A",3,1,"597a617139c2",0],["Complete combustion of methane produces:",["carbon monoxide and water","carbon dioxide and water","carbon and hydrogen","methanol"],"B",1,0,"28476fa147cb",0],["The balanced equation for complete combustion of methane is:",["CH₄ + O₂ → CO₂ + H₂O","CH₄ + 2O₂ → CO₂ + 2H₂O","2CH₄ + O₂ → 2CO + 4H₂","CH₄ + 3O₂ → CO₂ + 3H₂O"],"B",5,0,"56e798544d2b",0],["A gas heater in a closed room burns fuel with too little oxygen and produces a poisonous gas. The gas is:",["carbon dioxide","carbon monoxide","nitrogen","water vapour"],"B",3,1,"430259d1706f",0],["The main component of natural gas is:",["ethane","methane","propane","butane"],"B",1,0,"2c66c407247e",0],["LPG (liquefied petroleum gas) used in cylinders is mainly:",["methane and ethane","propane and butane","ethene and ethyne","hydrogen"],"B",3,0,"1c1099c50c5a",0],["Breaking large hydrocarbon molecules into smaller, more useful ones is called:",["cracking","polymerization","distillation","condensation"],"A",3,0,"ed34155105fc",0],["Polythene is made by joining many ethene molecules together. This process is:",["cracking","polymerization","hydrogenation","combustion"],"B",3,0,"2f4f05e4336b",0],["The molar mass of propane (C₃H₈) is (C = 12, H = 1):",["36 g mol⁻¹","44 g mol⁻¹","42 g mol⁻¹","48 g mol⁻¹"],"B",5,0,"9ce64a9326e8",0],["Which is the next member after propane in the alkane series?",["Butane","Ethane","Pentane","Propene"],"A",1,0,"855c9506f83a",0],["Methane is formed naturally in marshes and by animal digestion. It is also called:",["marsh gas","laughing gas","water gas","noble gas"],"A",3,0,"6929c1891ec5",0],["Alkynes are more reactive than alkanes because they contain:",["only single bonds","a triple bond","no carbon","ionic bonds"],"B",3,0,"3262f606a57f",0],["A student burns a hydrocarbon and gets a sooty yellow flame. This suggests:",["incomplete combustion","complete combustion","no combustion","the fuel is water"],"A",3,1,"f55552956b7a",0],["The general formula CₙH₂ₙ₋₂ belongs to the:",["alkanes","alkenes","alkynes","alcohols"],"C",3,0,"a8226fbd4fc2",0],["Alkenes are called unsaturated hydrocarbons because they contain:",["only single bonds","at least one carbon–carbon double bond","no hydrogen","oxygen atoms"],"B",3,0,"fef0018be32e",0],["Bromine water is shaken with hexane (an alkane). The orange-brown colour:",["disappears quickly","remains","turns blue","turns green"],"B",5,0,"1ba3013fe8b5",0],["Methane reacts with chlorine in sunlight and a hydrogen atom is replaced by chlorine. This is:",["addition","substitution","polymerization","cracking"],"B",3,0,"2e132f4ecc12",0],["Margarine is made by passing hydrogen through vegetable oil with a nickel catalyst. This reaction is:",["hydrogenation","dehydration","fermentation","combustion"],"A",3,1,"597a617139c2",0],["Burning a fuel in too little oxygen can produce the poisonous gas:",["carbon monoxide","oxygen","nitrogen","helium"],"A",3,1,"430259d1706f",0],["Plastic shopping bags made of polythene are formed by:",["cracking","polymerization of ethene","hydrogenation","fermentation"],"B",3,0,"2f4f05e4336b",0],["The gas supplied to homes through pipes in Pakistan (Sui gas) is mainly:",["methane","propane","butane","ethyne"],"A",1,1,"2c66c407247e",0],["The alkane that comes just before butane in the series is:",["Methane","Ethane","Propane","Pentane"],"C",1,0,"855c9506f83a",0],["The molecular formula of hexane is:",["C₆H₁₂","C₆H₁₆","C₆H₁₀","C₆H₁₄"],"D",3,0,"gen-chemistry-c14-formula",0],["The molecular formula of butyne is:",["C₄H₁₂","C₄H₁₀","C₄H₆","C₄H₈"],"C",3,0,"gen-chemistry-c14-formula",0],["The molecular formula of pentane is:",["C₅H₈","C₅H₁₂","C₅H₁₄","C₅H₁₀"],"B",3,0,"gen-chemistry-c14-formula",0],["The molecular formula of propane is:",["C₃H₈","C₃H₄","C₃H₁₀","C₃H₆"],"A",3,0,"gen-chemistry-c14-formula",0],["The molecular formula of hexene is:",["C₆H₁₂","C₆H₁₄","C₆H₁₆","C₆H₁₀"],"A",3,0,"gen-chemistry-c14-formula",0],["The molecular formula of pentyne is:",["C₅H₁₂","C₅H₁₀","C₅H₁₄","C₅H₈"],"D",3,0,"gen-chemistry-c14-formula",0],["The molar mass of propene (C₃H₆) is (C = 12, H = 1):",["42 g mol⁻¹","40 g mol⁻¹","56 g mol⁻¹","36 g mol⁻¹"],"A",3,0,"9ce64a9326e8",0],["The molar mass of hexene (C₆H₁₂) is (C = 12, H = 1):",["98 g mol⁻¹","84 g mol⁻¹","72 g mol⁻¹","82 g mol⁻¹"],"B",3,0,"9ce64a9326e8",0],["The molar mass of hexane (C₆H₁₄) is (C = 12, H = 1):",["72 g mol⁻¹","86 g mol⁻¹","84 g mol⁻¹","100 g mol⁻¹"],"B",3,0,"9ce64a9326e8",0],["The molar mass of pentene (C₅H₁₀) is (C = 12, H = 1):",["60 g mol⁻¹","70 g mol⁻¹","68 g mol⁻¹","84 g mol⁻¹"],"B",3,0,"9ce64a9326e8",0],["The molar mass of octene (C₈H₁₆) is (C = 12, H = 1):",["126 g mol⁻¹","96 g mol⁻¹","110 g mol⁻¹","112 g mol⁻¹"],"D",3,0,"9ce64a9326e8",0],["The molar mass of methane (CH₄) is (C = 12, H = 1):",["14 g mol⁻¹","12 g mol⁻¹","30 g mol⁻¹","16 g mol⁻¹"],"D",3,0,"9ce64a9326e8",0],["Complete combustion of one molecule of ethane (C₂H₆) produces:",["2 CO₂ and 3 H₂O","4 CO₂ and 3 H₂O","2 CO₂ and 6 H₂O","3 CO₂ and 2 H₂O"],"A",5,0,"gen-chemistry-c14-combustion-products",0],["Complete combustion of one molecule of butane (C₄H₁₀) produces:",["5 CO₂ and 4 H₂O","8 CO₂ and 5 H₂O","4 CO₂ and 5 H₂O","4 CO₂ and 10 H₂O"],"C",5,0,"gen-chemistry-c14-combustion-products",0],["Complete combustion of one molecule of butene (C₄H₈) produces:",["4 CO₂ and 4 H₂O","8 CO₂ and 4 H₂O","5 CO₂ and 5 H₂O","4 CO₂ and 8 H₂O"],"A",5,0,"gen-chemistry-c14-combustion-products",0],["Complete combustion of one molecule of methane (CH₄) produces:",["1 CO₂ and 4 H₂O","2 CO₂ and 2 H₂O","2 CO₂ and 1 H₂O","1 CO₂ and 2 H₂O"],"D",5,0,"gen-chemistry-c14-combustion-products",0],["Complete combustion of one molecule of hexane (C₆H₁₄) produces:",["6 CO₂ and 7 H₂O","7 CO₂ and 6 H₂O","6 CO₂ and 14 H₂O","12 CO₂ and 7 H₂O"],"A",5,0,"gen-chemistry-c14-combustion-products",0],["Complete combustion of one molecule of hexene (C₆H₁₂) produces:",["6 CO₂ and 12 H₂O","6 CO₂ and 6 H₂O","12 CO₂ and 6 H₂O","7 CO₂ and 7 H₂O"],"B",5,0,"gen-chemistry-c14-combustion-products",0],["A hydrocarbon has the molecular formula C₇H₁₆. Which conclusion is correct?",["It is an alkene","It is an alkyne","It is an alkane","It contains a double bond"],"C",3,0,"9b247da47370",1],["A student is given C₆H₁₄. The number of hydrogen atoms required by the alkane general formula is:",["10","12","14","16"],"C",3,0,"1a0a4e737623",1],["Which pair represents two consecutive members of the alkane homologous series?",["CH₄ and C₂H₄","C₂H₆ and C₃H₈","C₃H₈ and C₄H₈","C₄H₁₀ and C₆H₁₄"],"B",3,0,"3f92fa65e708",1],["An unknown compound follows the formula CₙH₂ₙ₊₂. Which structural feature must it have?",["At least one C=C bond","At least one C≡C bond","Only C–C single bonds in an open-chain structure","A carbonyl group"],"C",3,0,"1df1cf63ed0c",1],["Which compound contains the greatest number of hydrogen atoms?",["C₃H₈","C₄H₁₀","C₅H₁₂","C₆H₁₄"],"D",3,0,"33acb415d047",1],["A hydrocarbon contains 8 carbon atoms and belongs to the alkane series. Its molecular formula is:",["C₈H₁₆","C₈H₁₈","C₈H₁₄","C₈H₂₀"],"B",3,0,"308f8e600c36",1],["Which statement best explains why alkanes are called saturated hydrocarbons?",["They contain maximum possible carbon atoms","They contain only single bonds and the maximum number of hydrogen atoms","They dissolve completely in water","They contain oxygen along with carbon and hydrogen"],"B",3,0,"51f19f2c4923",1],["Which of the following is not an alkane?",["CH₄","C₂H₆","C₃H₈","C₄H₈"],"D",3,0,"6cb8b5ce420a",1],["A compound has the formula C₁₀H₂₂. According to the alkane formula, its carbon-to-hydrogen ratio is:",["1:2","5:11","10:11","11:5"],"B",3,0,"2ddab9bce80d",1],["If one CH₂ unit is added to propane while remaining within the same homologous series, the product is:",["Methane","Ethane","Butane","Pentane"],"C",3,0,"246b1182ed76",1],["Ethene is converted into ethane by adding:",["Cl₂","H₂","HCl","O₂"],"B",3,0,"bdc1f3d61d37",1],["The conversion C₂H₄ → C₂H₆ is an example of:",["Oxidation","Hydrogenation","Cracking","Halogenation"],"B",3,0,"14163ec9c03e",1],["During hydrogenation of an alkene, the hydrogen molecule is added across:",["A C–H single bond","A C=C double bond","A C–C single bond","A C–Cl bond"],"B",3,0,"97f07f8ee033",1],["A student carries out hydrogenation of ethene. Which combination is most appropriate?",["H₂ and Ni catalyst","Cl₂ and sunlight","O₂ and Zn","HCl and sunlight"],"A",3,0,"0c93a7c6e15a",1],["Which equation represents complete hydrogenation of ethyne?",["C₂H₂ + H₂ → C₂H₄","C₂H₂ + 2H₂ → C₂H₆","C₂H₂ + 3H₂ → C₂H₈","C₂H₂ + H₂ → C₂H₆"],"B",3,0,"b672e11b3ca0",1],["An alkyne requires two molecules of hydrogen for complete hydrogenation because it contains:",["Two carbon atoms","Two C–C single bonds","A C≡C triple bond","Two functional groups"],"C",3,0,"f63c7e67c2b1",1],["Which product is formed when propene undergoes complete hydrogenation?",["Propane","Propanol","Propyne","Propanal"],"A",3,0,"136b6ead2095",1],["A student uses nickel during hydrogenation but forgets to supply hydrogen gas. What is the major problem?",["Nickel becomes an alkene","Hydrogenation cannot occur because H₂ is required","The reaction automatically produces oxygen","Cracking takes place instead"],"B",3,0,"ef05608a9e7b",1],["Reduction of an alkyl halide generally involves:",["Replacement of hydrogen by halogen","Replacement of halogen by hydrogen","Addition of oxygen","Removal of carbon atoms"],"B",3,0,"0733ab19e33e",1],["When CH₃Cl is reduced, the main organic product is:",["CH₃OH","CH₄","C₂H₆","C₂H₄"],"B",3,0,"dff402958a30",1],["Which reagent combination is associated with the reduction of an alkyl halide to an alkane?",["Zn/HCl","Ni/H₂","Cl₂/sunlight","O₂/heat"],"A",3,0,"73c0ff82b1c2",1],["In the reduction of an alkyl halide, nascent hydrogen is important because it:",["Adds chlorine to the molecule","Replaces the halogen atom with hydrogen","Breaks every C–C bond","Converts the alkane into an alkene"],"B",3,0,"569d661111b6",1],["Which statement about nascent hydrogen is correct?",["It refers to stable H₂ gas stored in a cylinder","It is atomic hydrogen produced at the moment of its formation","It is hydrogen peroxide","It is a hydrocarbon"],"B",3,0,"d52125cec5fe",1],["A student wants to prepare an alkane from an alkyl halide. Which change should occur?",["X is replaced by H","H is replaced by X","C is replaced by O","H is replaced by OH"],"A",3,0,"cfced24bf737",1],["A large hydrocarbon molecule is heated strongly and breaks into smaller hydrocarbons. This process is called:",["Hydrogenation","Cracking","Reduction","Neutralization"],"B",3,0,"38e1cd73add3",1],["The main purpose of cracking is to:",["Convert small hydrocarbons into metals","Produce smaller, more useful hydrocarbons from larger ones","Convert alkanes directly into alcohols","Remove all carbon atoms"],"B",3,0,"bb6d02ab0d48",1],["Which combination of products is commonly obtained during cracking?",["Alcohols and acids","Alkanes and alkenes","Acids and bases","Only water"],"B",3,0,"85bec9163d0d",1],["Consider the reaction:\nC₁₀H₂₂ → C₈H₁₈ + X\nWhat is X?",["C₂H₂","C₂H₄","C₂H₆","CH₄"],"B",3,0,"65c54c70e70f",1],["In the reaction:\nC₁₂H₂₆ → C₈H₁₈ + X\nthe formula of X is:",["C₄H₈","C₄H₁₀","C₄H₆","C₄H₁₂"],"A",3,0,"86a65b5e0dc6",1],["Why is cracking important in petroleum processing?",["It converts all hydrocarbons into carbon dioxide","It produces smaller hydrocarbons that are more useful as fuels and raw materials","It removes hydrogen from every hydrocarbon","It produces only methane"],"B",3,0,"714ec94d332e",1],["A cracking reaction produces C₆H₁₄ and C₄H₈. The molecular formula of the original hydrocarbon could be:",["C₁₀H₂₂","C₁₀H₂₀","C₁₀H₂₄","C₁₀H₁₈"],"A",3,0,"ab902d4bef82",1],["Which observation indicates that one product of cracking is an alkene?",["It follows CₙH₂ₙ₊₂","It contains only single bonds","It follows CₙH₂ₙ for an open-chain compound","It contains no carbon"],"C",3,0,"8d05bbf74a7a",1],["Why are alkanes generally insoluble in water?",["They are ionic","They are largely non-polar","They contain oxygen","They react rapidly with water"],"B",3,0,"07b651150eed",1],["When an alkane is added to water, it generally:",["Forms a true solution","Reacts to form an acid","Remains as a separate layer","Produces hydrogen gas"],"C",3,0,"2ae3c86086a7",1],["Which statement about the boiling points of members of the alkane series is generally correct?",["They decrease continuously as chain length increases","They generally increase as molecular size increases","They remain exactly the same","They depend only on the number of hydrogen atoms"],"B",3,0,"1a09d4590840",1],["Why does the boiling point generally increase from methane to higher alkanes?",["Carbon atoms become ionic","Intermolecular attractions generally become stronger with increasing molecular size","Hydrogen atoms become radioactive","Alkanes become more polar than water"],"B",3,0,"c90d84f9f7fd",1],["Which alkane is expected to have the highest boiling point?",["Methane","Ethane","Propane","Pentane"],"D",3,0,"f302c4b929c2",1],["At room temperature, which physical state is expected for most alkanes containing 1–4 carbon atoms?",["Solid","Liquid","Gas","Plasma"],"C",3,0,"a5400291d2eb",1],["A student compares methane and octane. Which statement is most reasonable?",["Methane has a higher boiling point than octane","Octane generally has a higher boiling point than methane","Both have identical boiling points","Octane is always a gas at room temperature"],"B",3,0,"c7c4991b18c5",1],["Which property is most closely related to the increasing molecular size of alkanes?",["Increasing boiling point","Increasing ionic character","Increasing solubility in water","Formation of hydrogen bonds"],"A",3,0,"f7550f16af69",1],["The complete combustion of methane produces:",["CO and H₂ only","CO₂ and H₂O","C and H₂","CH₃OH and O₂"],"B",3,0,"ee3c59b62236",1],["Which equation is correctly balanced for complete combustion of methane?",["CH₄ + O₂ → CO₂ + H₂O","CH₄ + 2O₂ → CO₂ + 2H₂O","2CH₄ + O₂ → 2CO₂ + 2H₂O","CH₄ + 2O₂ → C + 2H₂O"],"B",3,0,"86a6b188e6ba",1],["Complete combustion of propane requires:",["3O₂","4O₂","5O₂","6O₂"],"C",3,0,"6c16bf5ec913",1],["Which observation best indicates that an alkane is undergoing combustion?",["Heat is absorbed without any products","Heat and light are released while oxygen is consumed","Hydrogen is always produced","The compound becomes an alkene without oxygen"],"B",3,0,"0665ab4b0ea7",1],["When oxygen supply is insufficient during combustion of an alkane, which harmful product may form?",["Carbon monoxide","Hydrogen chloride","Nitrogen","Methane only"],"A",3,0,"ce75a45f9a44",1],["Why are lighter alkanes commonly used as fuels?",["They cannot undergo combustion","Their combustion releases useful amounts of energy","They dissolve readily in water","They contain oxygen in their structures"],"B",3,0,"9892a707208a",1],["When methane reacts with chlorine in sunlight, the reaction is classified as:",["Addition","Substitution","Neutralization","Polymerization"],"B",3,0,"9240d6b8a522",1],["In the reaction:\nCH₄ + Cl₂ → CH₃Cl + HCl\nwhich atom has been substituted in methane?",["Carbon","Hydrogen","Chlorine","None"],"B",3,0,"752822af224e",1],["Why are alkanes generally described as relatively unreactive?",["Their carbon atoms have no electrons","Their C–C and C–H bonds are relatively strong and they are non-polar","They contain ionic bonds","They react instantly with water"],"B",3,0,"6126d6637a80",1],["A student is given the following processes:\nP: Ethene + H₂ → Ethane\nQ: Alkyl halide + nascent H → Alkane\nR: Large hydrocarbon → smaller hydrocarbons by heating\nS: Methane + Cl₂ → chloromethane + HCl in sunlight\nWhich option correctly identifies the processes?",["P—Hydrogenation, Q—Reduction, R—Cracking, S—Substitution","P—Reduction, Q—Hydrogenation, R—Substitution, S—Cracking","P—Cracking, Q—Substitution, R—Hydrogenation, S—Reduction","P—Substitution, Q—Cracking, R—Reduction, S—Hydrogenation"],"A",3,0,"063c7b297fa5",1],["Bilal's teacher writes a table about four alkanes. It gives each alkane's number of carbon atoms, its formula and its state at room temperature. Methane has 1 carbon atom. Its formula is CH₄, and it is a gas. Butane has 4 carbon atoms. Its formula is C₄H₁₀, and it is a gas. Hexane has 6 carbon atoms and is a liquid. Its formula is missing. Alkane X has 20 carbon atoms. Its formula and state are missing.\n\nWhat formula belongs in the empty box for hexane?",["C₆H₁₂","C₆H₁₄","C₆H₁₀","C₅H₁₂"],"B",5,1,"0f5f9d0fb148",1],["Bilal's teacher writes a table about four alkanes. It gives each alkane's number of carbon atoms, its formula and its state at room temperature. Methane has 1 carbon atom. Its formula is CH₄, and it is a gas. Butane has 4 carbon atoms. Its formula is C₄H₁₀, and it is a gas. Hexane has 6 carbon atoms and is a liquid. Its formula is missing. Alkane X has 20 carbon atoms. Its formula and state are missing.\n\nWhat is the state of alkane X at room temperature?",["Gas","Liquid","It cannot be told from the table","Solid"],"D",5,1,"b51becf7c969",1],["Bilal's teacher writes a table about four alkanes. It gives each alkane's number of carbon atoms, its formula and its state at room temperature. Methane has 1 carbon atom. Its formula is CH₄, and it is a gas. Butane has 4 carbon atoms. Its formula is C₄H₁₀, and it is a gas. Hexane has 6 carbon atoms and is a liquid. Its formula is missing. Alkane X has 20 carbon atoms. Its formula and state are missing.\n\nBilal pours a little hexane into a test tube of water. What will he see?",["The hexane forms a separate layer on top of the water","The hexane dissolves and the liquid looks clear","The hexane sinks to the bottom","The water turns into a gas"],"A",5,1,"e2bbfbbab892",1],["Bilal's teacher writes a table about four alkanes. It gives each alkane's number of carbon atoms, its formula and its state at room temperature. Methane has 1 carbon atom. Its formula is CH₄, and it is a gas. Butane has 4 carbon atoms. Its formula is C₄H₁₀, and it is a gas. Hexane has 6 carbon atoms and is a liquid. Its formula is missing. Alkane X has 20 carbon atoms. Its formula and state are missing.\n\nBilal learns that the hexane in his table gets oil out of cotton seeds. Why is it good for this?",["It reacts with the oil to make something new","It is an ionic compound","It does not react with most chemicals, so the oil is not changed","It is a solid at room temperature"],"C",5,1,"e51d1c2ebae2",1],["In winter, Hamza's family warms their room with a natural gas heater. Natural gas is mostly methane. With a window open, the heater burns with a blue flame. One cold night, the family shuts every door and window for hours. Black soot starts to collect on the wall above the heater.\n\nWhich equation shows the heater burning while the window is open?",["CH₄+O₂→CO₂+H₂O","3CH₄+4O₂→2CO+C+6H₂O","CH₄+2O₂→CO₂+2H₂O","CH₄+O₂→C+2H₂O"],"C",5,1,"413e732c2204",1],["In winter, Hamza's family warms their room with a natural gas heater. Natural gas is mostly methane. With a window open, the heater burns with a blue flame. One cold night, the family shuts every door and window for hours. Black soot starts to collect on the wall above the heater.\n\nWhy does soot start to form once the room is shut?",["Too little oxygen is left, so some carbon does not burn","The gas turns into a solid in the cold","Shutting the room gives the flame more oxygen","Methane has no carbon in it"],"A",5,1,"ce8927a8976c",1],["In winter, Hamza's family warms their room with a natural gas heater. Natural gas is mostly methane. With a window open, the heater burns with a blue flame. One cold night, the family shuts every door and window for hours. Black soot starts to collect on the wall above the heater.\n\nWhich harmful gas also forms in the shut room?",["Oxygen","Nitrogen","Hydrogen","Carbon monoxide"],"D",5,1,"fdd1ae14ba57",1],["In winter, Hamza's family warms their room with a natural gas heater. Natural gas is mostly methane. With a window open, the heater burns with a blue flame. One cold night, the family shuts every door and window for hours. Black soot starts to collect on the wall above the heater.\n\nWhat is the safest thing for Hamza's family to do?",["Move the heater into a smaller room","Keep a window a little open so fresh air reaches the flame","Turn the heater up higher","Cover the heater with a cloth"],"B",5,1,"131b126eb994",1],["A chemistry student is studying different methods for preparing alkanes. In one experiment, ethene (C₂H₄) is passed with hydrogen gas over finely divided nickel and heated. In another experiment, chloromethane (CH₃Cl) is treated with nascent hydrogen. The student also studies thermal cracking, in which a large hydrocarbon molecule breaks into smaller hydrocarbons. The teacher emphasizes that these reactions involve different chemical changes even though some of their products may be alkanes.\n\nWhat is the product formed when ethene reacts completely with hydrogen?",["Ethyne","Ethane","Ethanol","Methane"],"B",5,1,"9edd65346c7f",1],["A chemistry student is studying different methods for preparing alkanes. In one experiment, ethene (C₂H₄) is passed with hydrogen gas over finely divided nickel and heated. In another experiment, chloromethane (CH₃Cl) is treated with nascent hydrogen. The student also studies thermal cracking, in which a large hydrocarbon molecule breaks into smaller hydrocarbons. The teacher emphasizes that these reactions involve different chemical changes even though some of their products may be alkanes.\n\nThe conversion of ethene into ethane in the experiment is best classified as:",["Substitution","Cracking","Hydrogenation","Combustion"],"C",5,1,"1f3bf0de4c65",1],["A chemistry student is studying different methods for preparing alkanes. In one experiment, ethene (C₂H₄) is passed with hydrogen gas over finely divided nickel and heated. In another experiment, chloromethane (CH₃Cl) is treated with nascent hydrogen. The student also studies thermal cracking, in which a large hydrocarbon molecule breaks into smaller hydrocarbons. The teacher emphasizes that these reactions involve different chemical changes even though some of their products may be alkanes.\n\nWhen CH₃Cl reacts with nascent hydrogen, which change occurs?",["Cl is replaced by H","H is replaced by Cl","C–C bond is formed","A double bond is introduced"],"A",5,1,"00b05e8c939a",1],["A chemistry student is studying different methods for preparing alkanes. In one experiment, ethene (C₂H₄) is passed with hydrogen gas over finely divided nickel and heated. In another experiment, chloromethane (CH₃Cl) is treated with nascent hydrogen. The student also studies thermal cracking, in which a large hydrocarbon molecule breaks into smaller hydrocarbons. The teacher emphasizes that these reactions involve different chemical changes even though some of their products may be alkanes.\n\nWhich equation correctly represents the reduction of chloromethane?",["CH₃Cl + 2[H] → CH₄ + HCl","CH₃Cl + [H] → C₂H₆ + HCl","CH₃Cl + H₂ → CH₃OH + Cl₂","CH₃Cl → C + H₂ + Cl₂"],"A",5,1,"af6c1011cad4",1],["A chemistry student is studying different methods for preparing alkanes. In one experiment, ethene (C₂H₄) is passed with hydrogen gas over finely divided nickel and heated. In another experiment, chloromethane (CH₃Cl) is treated with nascent hydrogen. The student also studies thermal cracking, in which a large hydrocarbon molecule breaks into smaller hydrocarbons. The teacher emphasizes that these reactions involve different chemical changes even though some of their products may be alkanes.\n\nA large alkane undergoes thermal cracking and produces C₈H₁₈ and C₂H₄. What was the original hydrocarbon?",["C₁₀H₂₂","C₁₀H₂₀","C₁₀H₂₄","C₈H₁₈"],"A",5,1,"4b375be8d689",1],["A petroleum-processing plant separates several hydrocarbons for use as fuels. The chemist observes that smaller alkanes such as methane and propane are gases at room temperature, while larger alkanes may be liquids or solids. The hydrocarbons do not dissolve appreciably in water and generally have lower densities than water. During a combustion experiment, methane is burned with different amounts of oxygen. With sufficient oxygen, carbon dioxide and water are produced. When oxygen is limited, carbon monoxide may form.\n\nWhich property explains why these hydrocarbons do not dissolve appreciably in water?",["They are ionic","They are largely non-polar","They contain hydrogen bonds","They react rapidly with water"],"B",5,1,"9a10119d7174",1],["A petroleum-processing plant separates several hydrocarbons for use as fuels. The chemist observes that smaller alkanes such as methane and propane are gases at room temperature, while larger alkanes may be liquids or solids. The hydrocarbons do not dissolve appreciably in water and generally have lower densities than water. During a combustion experiment, methane is burned with different amounts of oxygen. With sufficient oxygen, carbon dioxide and water are produced. When oxygen is limited, carbon monoxide may form.\n\nWhich observation is most consistent with increasing alkane chain length?",["Boiling point generally decreases","Boiling point generally increases","All alkanes become gases","Solubility in water increases greatly"],"B",5,1,"230dbc58e2b6",1],["A petroleum-processing plant separates several hydrocarbons for use as fuels. The chemist observes that smaller alkanes such as methane and propane are gases at room temperature, while larger alkanes may be liquids or solids. The hydrocarbons do not dissolve appreciably in water and generally have lower densities than water. During a combustion experiment, methane is burned with different amounts of oxygen. With sufficient oxygen, carbon dioxide and water are produced. When oxygen is limited, carbon monoxide may form.\n\nWhich equation represents the complete combustion of methane?",["CH₄ + O₂ → CO + H₂O","CH₄ + 2O₂ → CO₂ + 2H₂O","CH₄ + 2O₂ → C + 2H₂O","2CH₄ + O₂ → 2CO₂ + 2H₂"],"B",5,1,"1b8d6afab93c",1],["A petroleum-processing plant separates several hydrocarbons for use as fuels. The chemist observes that smaller alkanes such as methane and propane are gases at room temperature, while larger alkanes may be liquids or solids. The hydrocarbons do not dissolve appreciably in water and generally have lower densities than water. During a combustion experiment, methane is burned with different amounts of oxygen. With sufficient oxygen, carbon dioxide and water are produced. When oxygen is limited, carbon monoxide may form.\n\nIf the oxygen supply becomes insufficient during methane combustion, which product may be formed?",["Carbon monoxide","Hydrogen chloride","Ethene","Nitrogen"],"A",5,1,"10ddb734f330",1],["A petroleum-processing plant separates several hydrocarbons for use as fuels. The chemist observes that smaller alkanes such as methane and propane are gases at room temperature, while larger alkanes may be liquids or solids. The hydrocarbons do not dissolve appreciably in water and generally have lower densities than water. During a combustion experiment, methane is burned with different amounts of oxygen. With sufficient oxygen, carbon dioxide and water are produced. When oxygen is limited, carbon monoxide may form.\n\nThe main reason lighter alkanes are widely used as fuels is that they:",["Are highly soluble in water","Release considerable heat during combustion","Cannot undergo chemical reactions","Contain oxygen in their molecules"],"B",5,1,"2b1facf354d7",1]]$j$::jsonb, true);
select public.prepify_load_bank('Chemistry', 15, $j$[["Biochemistry is the study of:",["chemical processes in living things","rocks and minerals","stars","metals only"],"A",1,0,"8e9496d8777d",0],["The molecular formula of glucose is:",["C₆H₁₂O₆","C₁₂H₂₂O₁₁","CH₄","C₂H₅OH"],"A",1,0,"7446a668a98a",0],["Glucose is an example of a:",["monosaccharide","disaccharide","polysaccharide","protein"],"A",3,0,"6ec0a643da44",0],["Sucrose (table sugar) is a:",["monosaccharide","disaccharide","polysaccharide","lipid"],"B",3,0,"bc0c5d90c846",0],["Starch and cellulose are:",["monosaccharides","disaccharides","polysaccharides","vitamins"],"C",3,0,"9812bb7eefce",0],["Proteins are made of long chains of:",["glucose","amino acids","fatty acids","nucleotides"],"B",1,0,"7db0b34b1b1b",0],["The bond that joins amino acids in a protein is the:",["peptide bond","ionic bond","hydrogen bond only","glycosidic bond"],"A",3,0,"6263078ec070",0],["Fats and oils belong to the group of:",["carbohydrates","proteins","lipids","vitamins"],"C",1,0,"042e1fd7ffe3",0],["Fats are formed from glycerol and:",["amino acids","fatty acids","glucose","nucleic acids"],"B",3,0,"6f464f69b7e8",0],["Enzymes are biological catalysts that are mostly made of:",["carbohydrates","proteins","lipids","minerals"],"B",3,0,"5c37be37f60b",0],["DNA and RNA are:",["carbohydrates","nucleic acids","lipids","vitamins"],"B",1,0,"9f650397d3dc",0],["A student adds iodine solution to a food sample and it turns blue-black. The food contains:",["starch","protein","fat","vitamin C"],"A",3,1,"0423d67aded9",0],["Benedict's solution turns brick-red when heated with:",["starch","a reducing sugar such as glucose","fat","protein"],"B",3,0,"0c90a03e6c0d",0],["The biuret test gives a violet (purple) colour with:",["proteins","starch","fats","glucose"],"A",3,0,"6580adf62e98",0],["A food sample leaves a translucent grease spot on paper. It contains:",["lipids","protein","starch","vitamin C"],"A",3,1,"dd77547a0e5d",0],["Vitamin C deficiency causes:",["rickets","scurvy","night blindness","anaemia"],"B",3,0,"70a0062721ec",0],["Vitamin D deficiency in children causes:",["scurvy","rickets","goitre","beriberi"],"B",3,0,"cfb5a29b47a6",0],["Night blindness is caused by a lack of:",["Vitamin A","Vitamin B","Vitamin C","Vitamin D"],"A",3,0,"bbd73dc627f7",0],["Which vitamins are fat-soluble?",["A, D, E and K","B and C","C only","B only"],"A",5,0,"f7f3dd97726b",0],["Sunlight helps the skin produce:",["Vitamin A","Vitamin C","Vitamin D","Vitamin K"],"C",1,0,"0ac9cf87c7fb",0],["A sailor on a long voyage without fresh fruit develops bleeding gums. The most likely cause is a lack of:",["vitamin C","vitamin D","protein","fat"],"A",5,1,"a357f3246da1",0],["The main function of carbohydrates in the body is to:",["provide energy","build muscles","carry genetic information","fight infection only"],"A",1,0,"17a60bffe2c0",0],["Proteins are needed mainly for:",["growth and repair of body tissues","quick energy only","making bones soft","storing genetic code"],"A",1,0,"ad4cffdc4fa6",0],["Which food is a good source of protein?",["Eggs","Sugar","Butter","Rice"],"A",1,0,"d7a614aec803",0],["Cellulose in our diet mainly provides:",["fibre (roughage) that helps digestion","quick energy","vitamins","protein"],"A",3,0,"8773c36fddb8",0],["Glycogen is the form in which animals store:",["glucose","fat","protein","vitamins"],"A",5,0,"928e49555665",0],["An enzyme stops working at very high temperatures because it:",["becomes denatured","turns into a vitamin","gains energy","dissolves in fat"],"A",5,0,"cb98634875d7",0],["Plants make glucose by photosynthesis using carbon dioxide, water and:",["sunlight","oxygen only","nitrogen","fat"],"A",3,0,"3e97f95e8622",0],["Which is a disaccharide found in milk?",["Lactose","Starch","Glucose","Cellulose"],"A",3,0,"ea2fac1bdf22",0],["A person on a diet of only white rice for months is at risk of lacking:",["protein and vitamins","carbohydrates","energy","starch"],"A",3,1,"9b17a31f4dfb",0],["Table sugar (sucrose) is made of two sugar units joined together. It is a:",["monosaccharide","disaccharide","polysaccharide","protein"],"B",3,0,"bc0c5d90c846",0],["Rice, bread and potatoes are rich in starch, which is a:",["monosaccharide","disaccharide","polysaccharide","lipid"],"C",1,0,"9812bb7eefce",0],["A food sample turns violet when biuret reagent is added. It contains:",["starch","protein","fat","glucose"],"B",3,1,"6580adf62e98",0],["A sample of fruit juice turns Benedict's solution brick-red on heating. It contains:",["a reducing sugar such as glucose","starch only","protein","fat"],"A",3,1,"0c90a03e6c0d",0],["Children who get little sunlight and no milk may develop soft, bent bones. This disease is:",["scurvy","rickets","goitre","night blindness"],"B",3,1,"cfb5a29b47a6",0],["Bleeding gums caused by a lack of fresh fruit and vegetables is the disease:",["scurvy","rickets","anaemia","beriberi"],"A",3,0,"70a0062721ec",0],["Amino acids join together to form:",["carbohydrates","proteins","fats","vitamins"],"B",1,0,"7db0b34b1b1b",0],["Athletes eat pasta before a race because carbohydrates mainly:",["provide energy","repair bones","carry genes","fight infection"],"A",1,1,"17a60bffe2c0",0],["Milk sugar is called:",["sucrose","lactose","starch","cellulose"],"B",3,0,"ea2fac1bdf22",0],["Heating an enzyme to 90 °C destroys its shape so it stops working. The enzyme has been:",["denatured","activated","multiplied","frozen"],"A",5,0,"cb98634875d7",0]]$j$::jsonb, true);
